window.MODULES["historia"].items.push(...[["Dos fuentes describen una huelga: un comunicado empresarial y una carta de los trabajadores. Sus relatos difieren.", "¿Cuál es el procedimiento historiográfico más sólido?", ["Contrastar autoría, contexto, intereses y otras evidencias", "Elegir la fuente más extensa", "Descartar ambas automáticamente", "Aceptar la fuente más reciente sin examen"], 0, "La crítica de fuentes exige contextualizar y contrastar testimonios."], ["Una comuna crece rápidamente, pero sus servicios de transporte y salud no aumentan al mismo ritmo.", "¿Qué problema de planificación se evidencia?", ["Desajuste entre expansión demográfica e infraestructura", "Reducción obligatoria de la población", "Desaparición de la movilidad", "Exceso de equipamiento en todos los sectores"], 0, "El crecimiento de población requiere coordinación con servicios."], ["Un país aumenta sus exportaciones, pero depende de un solo producto cuyo precio internacional es volátil.", "¿Qué vulnerabilidad presenta?", ["Exposición a cambios de precio externo", "Ausencia de comercio internacional", "Inexistencia de ingresos fiscales", "Diversificación productiva asegurada"], 0, "La concentración exportadora incrementa sensibilidad a shocks externos."], ["Una reforma electoral amplía el derecho a voto de grupos antes excluidos.", "¿Qué dimensión de la democracia modifica directamente?", ["La participación política formal", "La división climática", "La geografía física", "La productividad agrícola"], 0, "La ampliación del sufragio aumenta la inclusión política formal."], ["Un mapa histórico muestra rutas comerciales, pero no registra el trabajo de quienes transportaban mercancías.", "¿Qué límite de la fuente se identifica?", ["Representa circulación, pero invisibiliza ciertas experiencias sociales", "Demuestra que no había trabajadores", "Permite conocer todos los salarios", "Invalida cualquier estudio comercial"], 0, "La representación cartográfica puede omitir actores y relaciones sociales."], ["Dos regiones reciben el mismo monto de inversión pública, aunque una tiene el triple de habitantes.", "¿Qué indicador ayudaría a comparar la distribución?", ["Inversión por habitante", "Color del presupuesto", "Cantidad de páginas del informe", "Nombre de las capitales"], 0, "La comparación per cápita considera diferencias de población."], ["Una política pública aumenta la cobertura escolar, pero persisten diferencias grandes en resultados de aprendizaje.", "¿Qué conclusión es más defendible?", ["El acceso mejoró, pero la equidad en resultados sigue siendo un desafío", "La cobertura y la calidad son idénticas", "No hubo expansión de acceso", "Todos los estudiantes aprendieron lo mismo"], 0, "Acceso y resultados son dimensiones relacionadas pero distintas."], ["Una fotografía de una manifestación muestra pancartas, pero no permite observar qué ocurrió antes ni después.", "¿Qué limitación presenta?", ["Captura un instante que requiere contextualización", "Carece por definición de valor histórico", "Demuestra por sí sola el resultado político", "Permite conocer todas las motivaciones individuales"], 0, "La imagen documenta una escena, no toda la secuencia ni todas las causas."]] );
window.MODULES["m2"].items.push(...[["", "La función f(x)=x²−6x+5 tiene un mínimo. ¿Cuál es su valor mínimo?", ["−4", "−3", "0", "5"], 0, "El vértice está en x=3; f(3)=9−18+5=−4."], ["", "Si log₂(x−1)=3, ¿cuál es x?", ["7", "8", "9", "10"], 2, "x−1=2³=8, por lo que x=9."], ["", "Una progresión geométrica comienza con 3 y tiene razón 2. ¿Cuál es la suma de sus primeros 5 términos?", ["45", "63", "93", "96"], 2, "3(1+2+4+8+16)=3×31=93."], ["", "Una urna tiene 4 bolas rojas y 6 azules. Se extraen dos sin reposición. ¿Cuál es la probabilidad de que ambas sean rojas?", ["2/15", "4/25", "1/5", "3/10"], 0, "(4/10)×(3/9)=12/90=2/15."], ["", "La recta tangente a y=x² en x=3 tiene pendiente igual a:", ["3", "6", "9", "12"], 1, "La derivada es 2x; evaluada en 3 vale 6."], ["", "Si f(x)=2x−1 y g(x)=x², ¿cuánto vale g(f(3))?", ["5", "10", "25", "35"], 2, "f(3)=5; g(5)=25."], ["", "Una variable normal tiene media 100 y desviación estándar 15. ¿Cuál es el puntaje z de un valor 130?", ["1", "1,5", "2", "3"], 2, "z=(130−100)/15=2."], ["", "¿Cuántas contraseñas de tres dígitos distintos pueden formarse con 1,2,3,4,5 si el orden importa?", ["10", "15", "60", "125"], 2, "Variaciones sin repetición: 5×4×3=60."]] );
window.MODULES["lectura2"].items.push(...[["Un ensayo sostiene que la automatización no elimina necesariamente empleos, sino que transforma tareas; para fundamentarlo cita sectores donde surgieron nuevas ocupaciones, pero reconoce diferencias entre regiones.", "¿Qué conclusión mantiene la cautela del texto?", ["Toda automatización crea más empleo en cualquier región", "Los efectos laborales dependen del contexto y pueden incluir transformación de tareas", "La automatización no cambia las ocupaciones", "Los ejemplos prueban una ley universal"], 1, "El texto distingue transformación de tareas y variación contextual."], ["«Una ciudad puede tener muchos parques y, aun así, ser desigual: basta que los barrios periféricos carezcan de accesos seguros».", "¿Qué distinción conceptual sostiene el argumento?", ["Cantidad total versus distribución y accesibilidad", "Área verde versus precipitación", "Transporte público versus privado", "Tiempo pasado versus presente"], 0, "La existencia agregada no asegura acceso equitativo."], ["Un artículo afirma que una intervención mejoró los resultados, pero los participantes se ofrecieron voluntariamente y no hubo grupo de comparación.", "¿Cuál es la objeción metodológica más fuerte?", ["No es posible descartar selección previa ni otros factores como explicación", "El estudio necesariamente inventó los datos", "Los participantes nunca aprendieron", "La intervención no existió"], 0, "Sin comparación y asignación adecuada, la atribución causal es débil."], ["Un narrador describe una estación abandonada mediante ruidos que «persisten» y relojes que «se niegan a avanzar».", "¿Qué efecto produce la personificación?", ["Sugiere estancamiento temporal y memoria del lugar", "Presenta una explicación mecánica de los relojes", "Elimina toda subjetividad", "Confirma que la estación funciona"], 0, "Los objetos humanizados intensifican la sensación de detención."], ["Una crítica indica que el documental presenta testimonios conmovedores, aunque omite datos que permitirían estimar la frecuencia del fenómeno.", "¿Qué evaluación sintetiza mejor la crítica?", ["Eficacia testimonial con limitación para dimensionar el problema", "Rechazo completo de testimonios", "Demostración estadística concluyente", "Ausencia de dimensión emotiva"], 0, "Reconoce fuerza narrativa y carencia cuantitativa."], ["«No confundamos consenso con unanimidad: una decisión puede ser compartida sin borrar las discrepancias».", "¿Qué oposición conceptual se establece?", ["Acuerdo suficiente frente a ausencia total de disenso", "Velocidad frente a duración", "Norma frente a ley", "Emoción frente a información"], 0, "El consenso no exige eliminar toda diferencia."], ["Un reportaje usa una cifra nacional para describir la realidad de una localidad muy distinta del promedio.", "¿Qué error interpretativo puede cometer?", ["Trasladar un agregado a un contexto local sin evidencia específica", "Citar un dato numérico", "Utilizar lenguaje informativo", "Mencionar una localidad"], 0, "Un promedio nacional no describe necesariamente cada caso particular."], ["En un texto argumentativo, el autor presenta primero la mejor objeción a su postura y luego explica bajo qué condiciones sería válida.", "¿Qué estrategia utiliza?", ["Reconocimiento y delimitación de un contraargumento", "Ataque personal", "Repetición de la tesis sin evidencia", "Descripción cronológica"], 0, "Considera la objeción y precisa su alcance."]] );

(()=>{'use strict';
const modules=window.MODULES,subject=document.getElementById('subject'),status=document.getElementById('status'),count=document.getElementById('count'),mode=document.getElementById('mode'),quiz=document.getElementById('quiz');
let selected='',items=[],answers=[],pos=0,started=0,timer=null,finished=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const histKey=k=>'paes-trainer-v18-'+k+'-history',seenKey=k=>'paes-trainer-v19-'+k+'-seen';
const read=k=>{try{const v=JSON.parse(localStorage.getItem(k)||'[]');return Array.isArray(v)?v:[]}catch{return []}};
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function refresh(){selected=subject.value;const h=read(histKey(selected));document.getElementById('subject-title').textContent=modules[selected].title;status.textContent=`${modules[selected].items.length} preguntas · ${h.length} prácticas guardadas · ${h.length?Math.round(h.reduce((a,r)=>a+(Number(r.correct)||0),0)/Math.max(1,h.reduce((a,r)=>a+(Number(r.total)||0),0))*100):0}% aciertos históricos`;count.innerHTML=[5,10,20,30,40,65].filter(n=>n<=modules[selected].items.length).map(n=>`<option value="${n}">${n} preguntas</option>`).join('');if(!count.options.length)count.innerHTML='<option value="1">1 pregunta</option>';quiz.innerHTML='';clearInterval(timer)}
subject.onchange=refresh;
// Heuristic grouping by question demands, not position in the source bank.
// This is a practice filter, NOT official PAES psychometric calibration.
function questionLevel(q){
 const t=(String(q[0]||'')+' '+String(q[1]||'')).toLowerCase();
 const advanced=/inferenc|supuesto|sesgo|metodol|causal|generaliz|contradic|evidencia|argument|probabilidad condicion|desviaci[oó]n|derivad|logarit|funci[oó]n cuadr[aá]tica|distribuci[oó]n|correlaci[oó]n|interpretaci[oó]n cr[ií]tica/.test(t);
 const intermediate=/compar|analiz|relaci[oó]n|proporci[oó]n|porcent|ecuaci[oó]n|gr[aá]fic|modelo|justific|conclusi[oó]n|fuente|probabilidad/.test(t);
 return advanced?3:intermediate?2:1;
}
function start(){selected=subject.value;const all=modules[selected].items;const level=document.getElementById('difficulty')?.value||'mixto';const pool=all.map((q,i)=>({i,rank:questionLevel(q)})).filter(x=>level==='mixto'||x.rank===({basico:1,intermedio:2,avanzado:3}[level]||2)).map(x=>x.i);const usable=pool.length?pool:all.map((_,i)=>i);const n=Math.min(Number(count.value),usable.length);let seen=read(seenKey(selected)).filter(i=>Number.isInteger(i)&&i>=0&&i<all.length);let indices=shuffle(usable.filter(i=>!seen.includes(i))).slice(0,n);if(indices.length<n){indices.push(...shuffle(usable.filter(i=>!indices.includes(i))).slice(0,n-indices.length));seen=[]}localStorage.setItem(seenKey(selected),JSON.stringify([...new Set([...seen,...indices])]));items=indices.map(i=>({id:i,q:all[i]}));answers=Array(items.length).fill(null);pos=0;started=Date.now();finished=false;document.getElementById('setup').hidden=true;render();clearInterval(timer);timer=setInterval(()=>{const el=document.getElementById('clock');if(!el||finished)return;const remaining=Math.max(0,Math.round(items.length*140/65*60-(Date.now()-started)/1000));el.textContent=mode.value==='examen'?`⏱ ${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`:`⏱ ${Math.floor((Date.now()-started)/60000)} min`;if(mode.value==='examen'&&remaining===0)finish()},1000)}
function render(){const q=items[pos].q;quiz.innerHTML=`<section class="panel"><div class="quiz-head"><span class="pill">Pregunta ${pos+1} de ${items.length}</span><span class="pill" id="clock">⏱</span></div><div class="progress"><div style="width:${(pos+1)/items.length*100}%"></div></div>${q[0]?`<div class="source-text">${esc(q[0])}</div>`:''}<h2>${esc(q[1])}</h2><div class="options">${q[2].map((o,i)=>`<button class="opt ${answers[pos]===i?'selected':''}" data-answer="${i}"><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}</div><div id="feedback" aria-live="polite"></div></section><nav class="sticky"><button class="secondary" id="prev" ${pos===0?'disabled':''}>← Anterior</button><button id="next">${pos===items.length-1?'Finalizar':'Siguiente →'}</button></nav>`;
const feedback=document.getElementById('feedback');if(mode.value==='practica'&&answers[pos]!==null)feedback.innerHTML=`<div class="feedback">${answers[pos]===q[3]?'✓ Correcto':'✕ Incorrecto'} · ${esc(q[4])}</div>`;
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[pos]=Number(b.dataset.answer);render()});document.getElementById('prev').onclick=()=>{pos--;render();window.scrollTo(0,0)};document.getElementById('next').onclick=()=>{if(pos===items.length-1)finish();else{pos++;render();window.scrollTo(0,0)}}}
function finish(){if(finished)return;finished=true;clearInterval(timer);const ok=answers.reduce((s,a,i)=>s+Number(a===items[i].q[3]),0),h=read(histKey(selected));h.unshift({date:new Date().toISOString(),correct:ok,total:items.length,ids:items.map(x=>x.id),mode:mode.value});localStorage.setItem(histKey(selected),JSON.stringify(h));document.getElementById('setup').hidden=false;refresh();quiz.innerHTML=`<section class="panel"><h2>Resultado: ${ok} / ${items.length} · ${Math.round(ok/items.length*100)}%</h2><p>Guardado en el historial de ${esc(modules[selected].title)}.</p><details><summary>Ver correcciones</summary>${items.map((x,i)=>`<p><strong>${i+1}. ${esc(x.q[1])}</strong><br>${answers[i]===null?'Sin respuesta':esc(x.q[2][answers[i]])} · ${answers[i]===x.q[3]?'✓':'✕'}<br><span class="muted">${esc(x.q[4])}</span></p>`).join('')}</details><button id="again">Otra práctica</button></section>`;document.getElementById('again').onclick=()=>{quiz.innerHTML='';window.scrollTo(0,0)}}
document.getElementById('start').onclick=start;const requested=new URLSearchParams(location.search).get('materia');if(requested&&modules[requested])subject.value=requested;refresh();})();
